            StringBuilder sb = new StringBuilder();
            if (prefix != null) {
                sb.append(prefix);
            }

            for (int i = 0; i < minLength; i++) {
                sb.append((char) this.rnd.nextInt('a', 'z'));
            }

            final int m = 'z' - 'a';
            for (int n = number; n > 0; n = n / m) {
                sb.append((char) ('a' + n % m));
            }

            return sb.toString();
        }

