107	    /**
108	     * Returns nested node of the query model for the specified offset in the source text
109	     */
110	    public LexicalContextResolutionResult findLexicalContext(int textOffset) {
111	        List<SQLQueryNodeModel> nodePath = this.collectPathToContainingNode(textOffset);
112	        SQLQueryLexicalScopeItem lexicalItem = null;
113	        SQLQueryLexicalScope scope = null;
114	        SQLQuerySymbolOrigin deepestTailOrigin = null;
115	
116	        // walk up till the lexical scope covering given position
117	        // TODO consider corner-cases with adjacent scopes, maybe better use condition on lexicalItem!=null instead of the scope?
118	        for (int i = nodePath.size() - 1; i >= 0 && (scope == null || deepestTailOrigin == null); i--) {
119	            SQLQueryNodeModel node = nodePath.get(i);
120	            if (scope == null) {
121	                scope = node.findLexicalScope(textOffset);
122	                if (scope != null) {
123	                    lexicalItem = scope.findNearestItem(textOffset);
124	                }
125	            }
126	            if (deepestTailOrigin == null && node.getTailOrigin() != null) {
127	                deepestTailOrigin = node.getTailOrigin();
128	            }
129	        }
130	
131	        if (lexicalItem == null) {
132	            // table refs are not registered in lexical scopes properly for now (because rowsets model being build bottom-to-top),
133	            // so trying to find their components in the global list
134	            int index = STMUtils.binarySearchByKey(this.lexicalItems, n -> n.getSyntaxNode().getRealInterval().a, textOffset - 1, Comparator.comparingInt(x -> x));
135	            if (index < 0) {
136	                index = ~index - 1;
137	            }
138	            if (index >= 0) {
139	                SQLQueryLexicalScopeItem item = lexicalItems.get(index);
140	                Interval interval = item.getSyntaxNode().getRealInterval();
141	                if (interval.a < textOffset && interval.b + 1 >= textOffset) {
142	                    lexicalItem = item;
143	                }
144	            }
145	        }
146	
147	        SQLQuerySymbolOrigin symbolsOrigin = lexicalItem == null ? null : lexicalItem.getOrigin();
148	        if (symbolsOrigin == null && textOffset > this.getInterval().b) {
149	            symbolsOrigin = this.getTailOrigin();
150	            if (symbolsOrigin == null) {
151	                symbolsOrigin = deepestTailOrigin;
152	            }
153	        }
154	        if (symbolsOrigin == null && scope != null) {
155	            symbolsOrigin = scope.getSymbolsOrigin();
156	        }
157	
158	        return new LexicalContextResolutionResult(textOffset, lexicalItem, symbolsOrigin);
159	    }
160	
161	    @NotNull
162	    private List<SQLQueryNodeModel> collectPathToContainingNode(int textOffset) {
163	        List<SQLQueryNodeModel> nodePath = new ArrayList<>();
164	        SQLQueryNodeModel node = this;
165	        nodePath.add(node);
166	        SQLQueryNodeModel nested = node.findChildNodeContaining(textOffset);
167	        while (nested != null) {
168	            nodePath.add(nested);
169	            node = nested;
170	            nested = node.findChildNodeContaining(textOffset);
171	        }
172	        return nodePath;
173	    }
